def countSubIslands(grid1, grid2):
    rows, cols = len(grid1), len(grid1[0])
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid2[r][c] == 1:
                # Iterative DFS (avoids recursion limit on large islands)
                grid2[r][c] = 0
                stack = [(r, c)]
                is_sub = True
                while stack:
                    x, y = stack.pop()
                    # grid2 land but grid1 water: not a sub-island
                    if grid1[x][y] == 0:
                        is_sub = False
                    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid2[nx][ny] == 1:
                            grid2[nx][ny] = 0
                            stack.append((nx, ny))
                if is_sub:
                    count += 1
    return count
